fn main(){let p=std::env::args().nth(1).unwrap();let t=std::fs::read_to_string(p).unwrap();let f=nodecraft_step::StepFile::parse(&t).unwrap();for id in [84u32,85,86,87,88,90,91,92]{if let Some(e)=f.entities.get(&id){println!("#{} {} {:?}",id,e.name,e.args);}}let b=nodecraft_step::read_planar_body(&std::env::args().nth(1).unwrap());println!("{:?}",b.map(|b|(b.faces.len(),b.holes.len())));}
